-- Abort on ambiguous legacy records or category collisions, rather than create duplicates.
DO $$ BEGIN
 IF EXISTS (SELECT 1 FROM f1hist_p s JOIN public.piloto p ON p.codigo_fuente=s.codigo WHERE p.id_categoria IS DISTINCT FROM 1)
 OR EXISTS (SELECT 1 FROM f1hist_e s JOIN public.equipo e ON e.codigo_fuente=s.codigo WHERE e.id_categoria IS DISTINCT FROM 1)
 OR EXISTS (SELECT 1 FROM f1hist_gp s JOIN public.grandes_premios g ON g.codigo_fuente=s.codigo JOIN public.temporada t ON t.id_temporada=g.temporada_id WHERE t.anio<>s.anio OR g.id_categoria<>1 OR g.tipo_carrera<>'GP')
 THEN RAISE EXCEPTION 'Codigo fuente en conflicto con otra temporada o categoria'; END IF;
 IF EXISTS (SELECT 1 FROM f1hist_p s JOIN public.piloto p ON lower(p.nombre)=lower(s.nombre) AND lower(p.apellido)=lower(s.apellido) AND p.id_categoria=1 WHERE p.codigo_fuente IS DISTINCT FROM s.codigo)
 OR EXISTS (SELECT 1 FROM f1hist_e s JOIN public.equipo e ON lower(e.nombre)=lower(s.nombre) AND e.id_categoria=1 WHERE e.codigo_fuente IS DISTINCT FROM s.codigo)
 OR EXISTS (SELECT 1 FROM f1hist_c s JOIN public.circuito c ON lower(c.nombre)=lower(s.nombre) WHERE c.codigo_fuente IS DISTINCT FROM s.codigo)
 THEN RAISE EXCEPTION 'Registro maestro ambiguo: conciliar codigo_fuente antes de importar'; END IF;
 IF EXISTS (SELECT 1 FROM f1hist_gp s JOIN public.temporada t ON t.anio=s.anio JOIN public.grandes_premios g ON g.temporada_id=t.id_temporada AND g.fecha=s.fecha AND g.id_categoria=1 AND g.tipo_carrera='GP' WHERE g.codigo_fuente IS DISTINCT FROM s.codigo)
 THEN RAISE EXCEPTION 'GP previo con codigo diferente: conciliar antes de importar'; END IF;
END $$;

INSERT INTO public.temporada(anio,finalizada)
SELECT y,1 FROM generate_series(2011,2020) y
ON CONFLICT(anio) DO UPDATE SET finalizada=excluded.finalizada;
-- Keep the application's existing unique display code; preserve historical FIA codes separately.
-- Do not remove uq_piloto_categoria_codigo: legacy API writes can use codigo_fia.
ALTER TABLE public.piloto ADD COLUMN IF NOT EXISTS codigo_fia_original text;
COMMENT ON COLUMN public.piloto.codigo_fia_original IS
 'Abreviatura FIA de la fuente historica; codigo_fia puede ser un alias interno para evitar colisiones entre epocas.';

CREATE TEMP TABLE f1hist_p_codes ON COMMIT DROP AS
SELECT s.*, CASE s.codigo
 WHEN 'jean-eric-vergne' THEN 'JEV'
 WHEN 'michael-schumacher' THEN 'MSH'
 WHEN 'rio-haryanto' THEN 'RHY'
 ELSE s.fia END AS codigo_interno
FROM f1hist_p s;

DO $ BEGIN
 IF EXISTS (
   SELECT 1 FROM f1hist_p_codes s
   JOIN public.piloto p ON p.id_categoria=1 AND p.codigo_fia=s.codigo_interno
   WHERE p.codigo_fuente IS DISTINCT FROM s.codigo
     AND NOT EXISTS (SELECT 1 FROM public.piloto old WHERE old.codigo_fuente=s.codigo)
 ) OR EXISTS (
   SELECT codigo_interno FROM f1hist_p_codes
   WHERE codigo_interno IS NOT NULL GROUP BY codigo_interno HAVING count(*)>1
 ) THEN
  RAISE EXCEPTION 'Colision adicional de codigo FIA: revisar los alias historicos antes de importar';
 END IF;
END $;

INSERT INTO public.piloto(codigo_fuente,nombre,apellido,nacionalidad,fecha_nacimiento,numero,codigo_fia,codigo_fia_original,id_categoria)
SELECT s.codigo,s.nombre,s.apellido,s.pais,s.nacimiento,s.numero,s.codigo_interno,s.fia,1
FROM f1hist_p_codes s
WHERE NOT EXISTS (SELECT 1 FROM public.piloto p WHERE p.codigo_fuente=s.codigo)
ON CONFLICT(codigo_fuente) DO NOTHING;
INSERT INTO public.equipo(codigo_fuente,nombre,motor,pais,id_categoria)
SELECT codigo,nombre,motor,pais,1 FROM f1hist_e
ON CONFLICT(codigo_fuente) DO NOTHING;
INSERT INTO public.circuito(codigo_fuente,nombre,ciudad,pais,longitud_km,curvas)
SELECT codigo,nombre,ciudad,pais,longitud,curvas FROM f1hist_c
ON CONFLICT(codigo_fuente) DO NOTHING;
INSERT INTO public.equipos_temporada(equipo_id,temporada_id,register_name,monoplaza)
SELECT e.id_equipo,t.id_temporada,s.nombre,s.monoplaza FROM f1hist_et s
JOIN public.equipo e ON e.codigo_fuente=s.equipo JOIN public.temporada t ON t.anio=s.anio
ON CONFLICT(equipo_id,temporada_id) DO UPDATE SET register_name=excluded.register_name,monoplaza=excluded.monoplaza;
INSERT INTO public.pilotos_temporada(piloto_id,equipo_id,temporada_id,numero)
SELECT p.id_piloto,e.id_equipo,t.id_temporada,s.numero FROM f1hist_pt s
JOIN public.piloto p ON p.codigo_fuente=s.piloto JOIN public.equipo e ON e.codigo_fuente=s.equipo
JOIN public.temporada t ON t.anio=s.anio
ON CONFLICT(piloto_id,temporada_id) DO UPDATE SET equipo_id=excluded.equipo_id,numero=excluded.numero;
INSERT INTO public.grandes_premios(codigo_fuente,nombre_oficial,fecha,circuito_id,temporada_id,vueltas_totales,pole_position_piloto_id,tiempo_pole,vuelta_rapida_piloto_id,tiempo_vuelta_rapida,tipo_carrera,id_categoria,estado_gp)
SELECT s.codigo,s.nombre,s.fecha,c.id_circuito,t.id_temporada,s.vueltas,p.id_piloto,s.pole_tiempo,f.id_piloto,s.vr_tiempo,'GP',1,'V'
FROM f1hist_gp s JOIN public.circuito c ON c.codigo_fuente=s.circuito JOIN public.temporada t ON t.anio=s.anio
LEFT JOIN public.piloto p ON p.codigo_fuente=s.pole LEFT JOIN public.piloto f ON f.codigo_fuente=s.vr
ON CONFLICT(codigo_fuente) DO UPDATE SET nombre_oficial=excluded.nombre_oficial,fecha=excluded.fecha,circuito_id=excluded.circuito_id,temporada_id=excluded.temporada_id,vueltas_totales=excluded.vueltas_totales,pole_position_piloto_id=excluded.pole_position_piloto_id,tiempo_pole=excluded.tiempo_pole,vuelta_rapida_piloto_id=excluded.vuelta_rapida_piloto_id,tiempo_vuelta_rapida=excluded.tiempo_vuelta_rapida,tipo_carrera=excluded.tipo_carrera,estado_gp=excluded.estado_gp;
INSERT INTO public.resultados(grand_prix_id,piloto_id,equipo_id,posicion_final,posicion_inicio,vueltas_completadas,puntos_obtenidos,estado_resultado)
SELECT g.id_gp,p.id_piloto,e.id_equipo,s.final,s.inicio,s.vueltas,s.puntos,s.estado
FROM f1hist_r s JOIN public.grandes_premios g ON g.codigo_fuente=s.gp
JOIN public.piloto p ON p.codigo_fuente=s.piloto JOIN public.equipo e ON e.codigo_fuente=s.equipo
ON CONFLICT(grand_prix_id,piloto_id) DO UPDATE SET equipo_id=excluded.equipo_id,posicion_final=excluded.posicion_final,posicion_inicio=excluded.posicion_inicio,vueltas_completadas=excluded.vueltas_completadas,puntos_obtenidos=excluded.puntos_obtenidos,estado_resultado=excluded.estado_resultado;

-- Validate all source rows before commit (no silent losses from JOINs).
DO $$ BEGIN
 IF (SELECT count(*) FROM f1hist_gp s JOIN public.grandes_premios g ON g.codigo_fuente=s.codigo AND g.id_categoria=1 AND g.estado_gp='V' WHERE g.pole_position_piloto_id IS NOT NULL AND g.vuelta_rapida_piloto_id IS NOT NULL) <> 196
 THEN RAISE EXCEPTION 'Carga de GP incompleta'; END IF;
 IF (SELECT count(*) FROM f1hist_r s JOIN public.grandes_premios g ON g.codigo_fuente=s.gp JOIN public.piloto p ON p.codigo_fuente=s.piloto JOIN public.equipo e ON e.codigo_fuente=s.equipo JOIN public.resultados r ON r.grand_prix_id=g.id_gp AND r.piloto_id=p.id_piloto AND r.equipo_id=e.id_equipo) <> 4181
 THEN RAISE EXCEPTION 'Carga de resultados incompleta'; END IF;
 IF (SELECT count(*) FROM f1hist_pt s JOIN public.temporada t ON t.anio=s.anio JOIN public.piloto p ON p.codigo_fuente=s.piloto JOIN public.pilotos_temporada pt ON pt.piloto_id=p.id_piloto AND pt.temporada_id=t.id_temporada) <> 234
 OR (SELECT count(*) FROM f1hist_et s JOIN public.temporada t ON t.anio=s.anio JOIN public.equipo e ON e.codigo_fuente=s.equipo JOIN public.equipos_temporada et ON et.equipo_id=e.id_equipo AND et.temporada_id=t.id_temporada) <> 107
 THEN RAISE EXCEPTION 'Relaciones historicas incompletas'; END IF;
END $$;
COMMIT;

SELECT t.anio, count(DISTINCT g.id_gp) AS grandes_premios,
count(r.id_resultado) AS resultados, count(DISTINCT r.piloto_id) AS pilotos, count(DISTINCT r.equipo_id) AS equipos,
count(*) FILTER(WHERE r.posicion_final=1) AS ganadores
FROM public.temporada t JOIN public.grandes_premios g ON g.temporada_id=t.id_temporada AND g.id_categoria=1 AND g.tipo_carrera='GP'
LEFT JOIN public.resultados r ON r.grand_prix_id=g.id_gp
WHERE t.anio BETWEEN 2011 AND 2020 GROUP BY t.anio ORDER BY t.anio;
